#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."
role="${1:-merchant}"
platform="${2:-android}"
case "$role" in merchant) export EXPO_PUBLIC_APP_ROLE=MERCHANT;; driver) export EXPO_PUBLIC_APP_ROLE=DRIVER;; *) echo 'Use merchant or driver.' >&2; exit 2;; esac
case "$platform" in android|ios) ;; *) echo 'Use android or ios.' >&2; exit 2;; esac
if [ -z "${EXPO_PUBLIC_API_URL:-}" ]; then echo 'Set EXPO_PUBLIC_API_URL to the running API origin.' >&2; exit 2; fi
# Native folders are generated by Expo. Refuse to put a private keystore in a
# folder that prebuild may regenerate; the existing file is never moved/deleted.
if [ -n "${TOUSHIR_SIGNING_STORE_FILE:-}" ]; then
 signing_path="$(node -e 'process.stdout.write(require("fs").realpathSync(process.env.TOUSHIR_SIGNING_STORE_FILE))')"
 case "$signing_path" in "$PWD/android/"*|"$PWD/ios/"*) echo 'Keep the private keystore outside generated android/ios directories before building.' >&2; exit 2;; esac
fi
build_workers="${TOUSHIR_BUILD_WORKERS:-1}"
java_heap="${TOUSHIR_JAVA_HEAP:-1024m}"
export CMAKE_BUILD_PARALLEL_LEVEL="$build_workers"
./node_modules/.bin/expo prebuild --platform "$platform" --no-install
node scripts/mobile-verify.cjs --native "$platform"
if [ "$platform" = android ]; then
 (cd android && ./gradlew assembleRelease --no-daemon --console=plain --max-workers="$build_workers" -PreactNativeArchitectures=arm64-v8a -Dorg.gradle.parallel=false -Dorg.gradle.jvmargs="-Xmx$java_heap -XX:MaxMetaspaceSize=384m")
 mkdir -p build/downloads
 cp android/app/build/outputs/apk/release/app-release.apk "build/downloads/toushir-${role}.apk"
 echo "Built build/downloads/toushir-${role}.apk"
else
 (cd ios && pod install)
 bash scripts/prepare-ios-framework.sh
 workspaces=(ios/*.xcworkspace)
 workspace="${workspaces[0]}"
 scheme="$(basename "$workspace" .xcworkspace)"
 xcodebuild -workspace "$workspace" -scheme "$scheme" -configuration Release -sdk iphonesimulator -destination "generic/platform=iOS Simulator" -derivedDataPath "${TOUSHIR_IOS_DERIVED_DATA:-${TMPDIR:-/tmp}/toushir-ios-${role}}" -jobs 2 build
 mkdir -p "build/ios-${role}"
 COPYFILE_DISABLE=1 cp -R "${TOUSHIR_IOS_DERIVED_DATA:-${TMPDIR:-/tmp}/toushir-ios-${role}}/Build/Products/Release-iphonesimulator/${scheme}.app" "build/ios-${role}/"
 mkdir -p build/downloads
 ditto -c -k --norsrc --keepParent "${TOUSHIR_IOS_DERIVED_DATA:-${TMPDIR:-/tmp}/toushir-ios-${role}}/Build/Products/Release-iphonesimulator/${scheme}.app" "build/downloads/toushir-${role}-ios-simulator.zip"
fi
